/** Explicit engineering fixture, generated by the formal fake worker in an isolated stopped copy. */
import { resolve, join } from 'node:path';
import { randomUUID } from 'node:crypto';
import { holdDispatchGate } from '../../src/persistence/daemonState.ts';
import { openDatabase } from '../../src/persistence/db.ts';
import { dispatchDaemonCommand } from '../../src/daemon/commands.ts';
import { DispatchWorker } from '../../src/daemon/dispatchWorker.ts';
import { FakeRuntimeAdapter } from '../../src/adapter/fake/runtimeAdapter.ts';
import { TASK_COMPLETE_SCHEMA_VERSION } from '../../src/contracts/prompts.ts';

async function main() {
  const dataRoot = resolve(process.argv[2]!);
  if (!dataRoot.startsWith(resolve('dist/desktop/r76-images-')) || !dataRoot.endsWith(join('copy', 'server-data'))) throw new Error('fixture requires own isolated copy');
  const db = openDatabase(join(dataRoot, 'state.sqlite'));
  const pid = process.argv[3]!; const roomId = process.argv[4]!;
  const room = db.prepare('SELECT id FROM conversations WHERE room_id=?').get(roomId) as { id: string };
  const member = db.prepare("SELECT id FROM project_members WHERE project_id=? AND principal_type='agent' LIMIT 1").get(pid) as { id: string };
  const final = JSON.stringify({ schemaVersion: TASK_COMPLETE_SCHEMA_VERSION, resultKey: 'engineering', changeSummary: 'R76 工程成果入口夹具；并非真实模型交付', files: ['中文图片.png'], executedVerifications: [], unexecutedVerifications: [], remainingIssues: [] });
  const adapter = new FakeRuntimeAdapter({ turnScriptSequencer: () => [
    { kind: 'event', event: { kind: 'message.completed', messageId: 'r76-fixture', text: final } },
    { kind: 'event', event: { kind: 'turn.completed', finalText: final } },
  ] });
  try {
    const r = await dispatchDaemonCommand({ db, localUserId: 'u_local', appDataDir: dataRoot, interruptTurn: async () => {} }, {
      protocolVersion: 1, commandId: `r76-fixture-${randomUUID()}`, method: 'message.submit', params: {
        target: { kind: 'room_root', projectId: pid, roomId, conversationId: room.id }, body: '工程图片成果入口夹具', intent: 'default', mentions: [{ kind: 'member', memberId: member.id }],
      },
    }) as { ok: boolean };
    if (!r.ok) throw new Error('fixture submit failed');
    await new DispatchWorker({ db, adapter, leaseOwner: 'r76-fixture', appDataDir: dataRoot }).runOnce();
    await new Promise(r => setTimeout(r, 300));
    const delivery = db.prepare('SELECT d.id, t.conversation_thread_id AS threadId FROM task_deliveries d JOIN tasks t ON t.id=d.task_id ORDER BY d.rowid DESC LIMIT 1').get() as { id: string; threadId: string } | undefined;
    if (delivery == null) throw new Error('fake fixture delivery not stored');
    if ((db.prepare('SELECT count(*) c FROM real_calls').get() as { c: number }).c !== 0) throw new Error('fixture must have zero real calls');
    if ((db.prepare("SELECT count(*) c FROM outbox WHERE status IN ('pending','leased')").get() as {c:number}).c !== 0) throw new Error('fixture still has pending work');
    holdDispatchGate(db); // Protect the engineering fixture when the real launcher reopens it.
    console.log(JSON.stringify(delivery));
  } finally { await adapter.closeAllSessions(); db.close(); }
}
void main();
